mapper.select:
        SELECT m.*
		FROM musical AS m
		JOIN tag_connection AS c ON m.musical_id = c.musical_id
		JOIN hashtag AS t ON c.tag_id = t.tag_id
		LEFT JOIN like_musical AS l ON m.musical_id = l.musical_id



                t.tag IN

                    #{tag}



            		AND m.title like CONCAT ('%', #{keyword}, '%')


            		AND m.theater like CONCAT ('%', #{theater}, '%')


	            AND #{date} BETWEEN m.start_date AND m.end_date


			    AND m.start_date > #{fromDate}


		        AND m.start_date <= #{endDate}


		        AND m.end_date >= #{startDate}



        GROUP BY m.musical_id


                ORDER BY RAND()


                ORDER BY COUNT(l.musical_id) ${order}


                ORDER BY m.title ${order}


                ORDER BY m.musical_id ${order}


               	ORDER BY m.musical_id DESC




            	LIMIT #{size} OFFSET #{offset}

SELECT m.* FROM musical as m JOIN like_musical as l
ON m.musical_id = l.musical_id
WHERE user_id = #{userId}
ORDER BY m.musical_id;
